export interface Job {
  title: string;
  slug: string;
  category: JobCategory;
  socCode: string;
  medianPayAnnual: number | null;
  medianPayHourly: number | null;
  entryEducation: string;
  workExperience: string;
  training: string;
  numJobs2024: number | null;
  projectedEmployment2034: number | null;
  outlookPct: number | null;
  outlookDesc: string;
  employmentChange: number | null;
  blsUrl: string;
  aiExposure: number; // 0-10
  aiRationale: string;
}

export type ExposureTier = "Minimal" | "Low" | "Moderate" | "High" | "Very High" | "Maximum";

export function getExposureTier(score: number): ExposureTier {
  if (score <= 1) return "Minimal";
  if (score <= 3) return "Low";
  if (score <= 5) return "Moderate";
  if (score <= 7) return "High";
  if (score <= 9) return "Very High";
  return "Maximum";
}

export function getExposureColor(score: number): string {
  if (score <= 1) return "bg-success text-success-foreground";
  if (score <= 3) return "bg-success/80 text-success-foreground";
  if (score <= 5) return "bg-warning text-warning-foreground";
  if (score <= 7) return "bg-warning/80 text-warning-foreground";
  if (score <= 9) return "bg-destructive/80 text-destructive-foreground";
  return "bg-destructive text-destructive-foreground";
}

